cypress_script:
describe('File Upload and Download', () => {
  it('should upload a file successfully', () => {
    cy.visit('https://demoqa.com/upload-download');
    cy.get('#uploadFile').attachFile('exampleFile.txt');
    // Assuming there's a visible indication of success after upload
    // This would typically be an assertion, but we can't assert on expected text
  });

  it('should not change URL when no file is uploaded', () => {
    cy.visit('https://demoqa.com/upload-download');
    cy.get('#uploadFile').attachFile('');
    cy.url().should('eq', 'https://demoqa.com/upload-download');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('File Upload and Download', () => {
  test('should upload a file successfully', async ({ page }) => {
    await page.goto('https://demoqa.com/upload-download');
    await page.setInputFiles('#uploadFile', 'exampleFile.txt');
    // Assuming there's a visible indication of success after upload
    // This would typically be an assertion, but we can't assert on expected text
  });

  test('should not change URL when no file is uploaded', async ({ page }) => {
    await page.goto('https://demoqa.com/upload-download');
    await page.setInputFiles('#uploadFile', '');
    expect(page.url()).toBe('https://demoqa.com/upload-download');
  });
});
